 function checkoutContent(){if(!cart.length)return `<div class="empty-state"><h3>Your bag is empty.</h3><p>Add an available demo product with a valid size before entering checkout.</p>${btn('products.html','Shop Products')}</div>`;return `<form id="checkout-form" class="checkout-layout" novalidate><div><div class="form-card"><h2>Your Information</h2><div class="form-grid">${inputField('check-name','Full Name *','text','required minlength="2" maxlength="70" autocomplete="name" title="Letters and spaces only"')}${inputField('check-email','Email Address *','email','required autocomplete="email"')}${inputField('check-phone','Phone Number *','tel','required inputmode="numeric" maxlength="10" pattern="[0-9]{10}" autocomplete="tel"')}</div></div><div class="form-card"><h2>Delivery Details</h2><div class="form-grid">${inputField('check-address','Address Line 1 *','text','required minlength="5" autocomplete="address-line1"')}${inputField('check-address2','Address Line 2','text','autocomplete="address-line2"')}${inputField('check-city','City *','text','required minlength="2" autocomplete="address-level2"')}${inputField('check-state','State *','text','required minlength="2" autocomplete="address-level1"')}${inputField('check-pin','PIN Code *','text','required inputmode="numeric" maxlength="6" pattern="[0-9]{6}" autocomplete="postal-code"')}<div class="form-field"><label for="check-country">Country</label><select class="select" id="check-country" name="check-country"><option value="India">India (demo)</option></select></div></div></div><div class="form-card"><h2>Demo Payment Selection</h2><p>No financial information is requested or processed.</p><label class="radio-card"><input type="radio" name="demo-payment" value="Demo Card" checked/><span><strong>Demo Card Payment</strong><br/><span class="hint">Simulation only — no card details entered.</span></span></label><label class="radio-card"><input type="radio" name="demo-payment" value="Demo Cash on Delivery"/><span><strong>Demo Cash on Delivery</strong><br/><span class="hint">No physical delivery will happen.</span></span></label><label class="form-check"><input type="checkbox" name="demo-ack" required/> I understand this is a demonstration and no real order or payment will be made.</label><div id="checkout-feedback" role="status" aria-live="polite"></div></div></div><aside class="summary-card"><h3>Demo Order Summary</h3>${cart.map(x=>{let p=byId(x.id);return `<div class="summary-line"><span>${p.name}<br/><small>${x.size} · ${x.color} × ${x.qty}</small></span><strong>${money(p.price*x.qty)}</strong></div>`}).join('')}<div class="summary-line"><span>Subtotal</span><strong>${money(cartTotal())}</strong></div><div class="summary-line"><span>Demo shipping (not a live offer)</span><strong>₹0</strong></div><div class="summary-line total"><span>Illustrative total</span><span>${money(cartTotal())}</span></div><button type="submit" class="btn primary block">Complete Demo Checkout ${ico('arrow',16)}</button><p class="hint">No real payment, email or shipment will occur.</p></aside></form>`}
 function cartKey(x){return [x.id,x.size,x.color].join('|')}
 function cartTotal(){return cart.reduce((s,x)=>s+(byId(x.id)?.price||0)*x.qty,0)}
